1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	
46	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	};
51	
52	/** Percentages are applied as integer arithmetic so that the final
53	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
54	const addPercent = (amount: number, percent: number): number =>
55	  amount + (amount * percent) / 100;
56	
57	/** Rounds up — premiums round in the MHPCO's favour. */
58	const roundPremium = (amount: number): number => Math.ceil(amount);
59	
60	const itemBasePremium = (item: Item): number =>
61	  BASE_PREMIUM_BY_TYPE[item.type];
62	
63	const policyBasePremium = (items: Item[]): number =>
64	  items.reduce((total, item) => total + itemBasePremium(item), 0);
65	
66	const quote = (step: QuoteStep): StepResult => {
67	  const basePremium = policyBasePremium(step.items);
68	  const premium =
69	    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
70	  return { premium: roundPremium(premium) };
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioResult => {
74	  const results = scenario.steps.map((step) => quote(step as QuoteStep));
75	  return { results };
76	};
